 31	\section{The pulled-apart measurements and observables}
 32	
 33	The measurement $\{\hat{S}_{g_X,g_Z}\}$ reads out an $X$-polynomial and a $Z$-polynomial simultaneously. We now separate the two readings again, this time as commuting actions on distinct registers: the polynomial outcome is measured on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), while a genuine Pauli measurement acts on the EPR register $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
 34	
 35	\begin{definition}[Single-basis marginals of the polynomial-pair measurement]\label{def:s-w-marginals}
 36		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly}
 37		\leanok
 38		\uses{lem:qld-4-7}
 39		Let $\{\hat{S}_{g_X,g_Z}\}$ be the projective measurement of Lemma~\ref{lem:qld-4-7}. For every $g \in \mathrm{ideg}_{d,m}(\F_q)$ define
 40		\[
 41			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 42			\qquad \text{and} \qquad
 43			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 44		\]
 45		the sums ranging over $\mathrm{ideg}_{d,m}(\F_q)$. Since $\{\hat{S}_{g_X,g_Z}\}$ is projective, its elements are mutually orthogonal projectors; hence each $\hat{S}^W_g$, for $W \in \{X,Z\}$, is a projector, and $\{\hat{S}^W_g\}_{g}$ is a projective measurement with outcomes in $\mathrm{ideg}_{d,m}(\F_q)$.
 46	\end{definition}
 47	
 48	\begin{definition}[Pauli dot-product projectors]\label{def:tau-dot-product-projector}
 49		\lean{MIPStarRE.QPBT.tauDotProj}
 50		\leanok
 51		\uses{def:generalized-pauli}
 52		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the projector
 53		\begin{equation}\label{eq:def-tauwu}
 54			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
 55		\end{equation}
 56		For each fixed $\tilde{u}$, the family $\{\tau^W_a(\tilde{u})\}_{a \in \F_q}$ is a projective measurement on $(\C^q)^{\ot M}$.
 57	\end{definition}
 58	
 59	\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
 60		\lean{MIPStarRE.QPBT.tildeM}
 61		\leanok
 62		\uses{def:s-w-marginals, def:tau-dot-product-projector, def:decoding-map}
 63		For all $W \in \{X,Z\}$ and $\tilde{u} \in \F_q^{M}$ define the measurement $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ by
 64		\begin{equation}\label{eq:tilde_M}
 65			\tilde{M}^{W,\tilde{u}}_a = \sum_{g} \hat{S}^W_g \ot \tau_{(\mathrm{Dec}(g) \cdot \tilde{u}) - a}^W(\tilde{u})\;,
 66		\end{equation}
 67		the sum ranging over $g \in \mathrm{ideg}_{d,m}(\F_q)$. If $\hat{S}^W_g$ is viewed as an operator acting on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), then $\tilde{M}^{W,\tilde{u}}_a$ acts on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ (resp.\ $\mathrm{B}\mathrm{B}'\mathrm{B}''$), the $\tau^W$ factor acting on $\mathrm{A}''$ (resp.\ $\mathrm{B}''$). Each family $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ is a projective measurement, because the $\hat{S}^W_g$ and the $\tau^W$ projectors are projective and, for each $g$, the projectors $\tau^W_{(\mathrm{Dec}(g)\cdot\tilde{u})-a}(\tilde{u})$ sum to the identity as $a$ ranges over $\F_q$.
 68	\end{definition}
 69	
 70	\begin{definition}[Pulled-apart Pauli observables]\label{def:tilde-w-observables}
 71		\lean{MIPStarRE.QPBT.tildeObs}
 72		\leanok
 73		\uses{def:tilde-m-measurement, def:dual-self-dual-normal-basis, def:binary-representation, def:subfield-trace}
 74		Let $\{e_j\}_{j \in \{1,\ldots,t\}}$ be the self-dual normal basis for $\F_q$ over $\F_2$ (Definition~\ref{def:dual-self-dual-normal-basis}) that is fixed once and for all in Definition~\ref{def:binary-representation}, and let $\tr = \tr_{q \to 2} \colon \F_q \to \F_2$ be the subfield trace. For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^M$, and $j \in \{1,\ldots,t\}$ define the operator
 75		\begin{equation}\label{eq:def-tildewj}
 76			\tilde{W}^j(\tilde{u}) = \sum_{a \in \F_q} (-1)^{\tr(e_j a)} \, \tilde{M}_a^{W,\tilde{u}}\;,
 77		\end{equation}
 78		acting on the same registers as $\tilde{M}^{W,\tilde{u}}_a$.
 79	\end{definition}
 80	
 81	% In the source the following properties are stated inline with the
 82	% definition of the observables; they are recorded here as a lemma.
 83	\begin{lemma}[Product form and Pauli relations of the pulled-apart observables]\label{lem:tildew-product-form}
 84		\lean{MIPStarRE.QPBT.tildeObs_eq_heteroKron}
 85		\lean{MIPStarRE.QPBT.tildeObs_isHermitian}
 86		\lean{MIPStarRE.QPBT.tildeObs_mul_self}
 87		\lean{MIPStarRE.QPBT.tildeObs_twisted_commutation}
 88		\leanok
 89		\uses{def:tilde-w-observables, def:s-w-marginals, def:generalized-pauli, def:decoding-map, lem:qld-4-7}
 90		Let $\tau^W(\cdot)$ denote the generalized Pauli $W$ observable (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^M$, and $j \in \{1,\ldots,t\}$,
 91		\begin{equation}\label{eq:tildewj-product-form}
 92			\tilde{W}^j(\tilde{u})
 93			= \Big( \sum_{g_X,g_Z} (-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \hat{S}_{g_X,g_Z} \Big) \ot \tau^W(e_j \tilde{u})\;,
 94		\end{equation}
 95		where $g_W$ denotes $g_X$ if $W = X$ and $g_Z$ if $W = Z$. In particular each $\tilde{W}^j(\tilde{u})$ is Hermitian and squares to the identity. Moreover, the pulled-apart observables satisfy exactly the twisted commutation relations of the generalized Pauli observables $\tau^X(e_j \tilde{u})$ and $\tau^Z(e_{j'} \tilde{v})$: for all $j,j' \in \{1,\ldots,t\}$ and $\tilde{u},\tilde{v} \in \F_q^M$,
 96		\begin{equation}\label{eq:tildew-twisted-commutation}
 97			\tilde{X}^j(\tilde{u})\, \tilde{Z}^{j'}(\tilde{v})
 98			= (-1)^{\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v}))}\, \tilde{Z}^{j'}(\tilde{v})\, \tilde{X}^j(\tilde{u})\;,
 99		\end{equation}
100		where $\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v})) = \tr(e_j e_{j'} (\tilde{u} \cdot \tilde{v}))$.
101	\end{lemma}
102	\begin{proof}
103		\uses{def:tilde-w-observables, def:tilde-m-measurement, def:tau-dot-product-projector, def:s-w-marginals, lem:pauli-observable-expansion, lem:twisted-commutation, lem:qld-4-7}
104		Expanding $\tau^W(e_j \tilde{u}) = \sum_{h} (-1)^{\tr(e_j (\tilde{u} \cdot h))}\, \tau^W_h$ on the right-hand side of \eqref{eq:tildewj-product-form} (Lemma~\ref{lem:pauli-observable-expansion}), grouping the $h$ according to the value $a' = h \cdot \tilde{u}$ into the projectors $\tau^W_{a'}(\tilde{u})$ of \eqref{eq:def-tauwu}, collecting the pairs $(g_X,g_Z)$ with a common value $g_W = g$ into $\hat{S}^W_g$ (Definition~\ref{def:s-w-marginals}), and changing the summation variable to $a = (\mathrm{Dec}(g) \cdot \tilde{u}) - a'$ recovers, by \eqref{eq:tilde_M} and \eqref{eq:def-tildewj}, the operator $\tilde{W}^j(\tilde{u})$; this proves \eqref{eq:tildewj-product-form}. Since the $\hat{S}_{g_X,g_Z}$ are mutually orthogonal projectors summing to the identity (Lemma~\ref{lem:qld-4-7}) and $\tau^W(e_j \tilde{u})$ is a Hermitian involution, the product form exhibits $\tilde{W}^j(\tilde{u})$ as Hermitian with square $\sum_{g_X,g_Z} \hat{S}_{g_X,g_Z} \ot \Id = \Id$. For \eqref{eq:tildew-twisted-commutation}, the two sign-weighted sums of the projectors $\hat{S}_{g_X,g_Z}$ appearing in the product forms of $\tilde{X}^j(\tilde{u})$ and $\tilde{Z}^{j'}(\tilde{v})$ commute with each other, so the commutation phase is that of $\tau^X(e_j \tilde{u})$ and $\tau^Z(e_{j'} \tilde{v})$, which is $(-1)^{\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v}))}$ by Lemma~\ref{lem:twisted-commutation}.
105	\end{proof}
