114	\section{Consistency with the points measurements}
115	
116	The next lemma shows that the pulled-apart measurements are consistent with the original points measurements of the strategy, and self-consistent. In its statement, and for the remainder of the chapter, $\delta_S$ denotes the function of Lemma~\ref{lem:qld-4-7}, enlarged by an adjustment of the universal constants $a$ and $b$ so as to also dominate additional error terms of order $\sqrt{\eps}$, $\eps$, and $md/q$ that the source absorbs into $\delta_S$ along the way; such an adjustment is possible since, after shrinking $b$ to at most $1/2$, the term $\eps^b$ dominates $\sqrt{\eps}$ and $\eps$ for $\eps \leq 1$, while $(md)^a q^{-b}$ dominates $md/q$.
117	
118	\begin{lemma}[Consistency and self-consistency of the pulled-apart measurements]\label{lem:qld-construct-the-paulis}
119		\lean{MIPStarRE.QPBT.tildeM_consistent_pointMeas}
120		\lean{MIPStarRE.QPBT.tildeM_consistent_pointMeas'}
121		\lean{MIPStarRE.QPBT.tildeObs_selfConsistent}
122		\leanok
123		\uses{def:tilde-m-measurement, def:tilde-w-observables,
124			lem:projective-strategy-setup, def:expanded-state, def:consistency,
125			def:approx-question-indexed-operators, lem:qld-4-7,
126			def:indicator-vector}
127		The measurements $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ and observables $\tilde{W}^j(\tilde{u})$ satisfy the following properties.
128		% The paper's statement also quantifies item 1 over j, but j does not occur
129		% in item 1; the vacuous quantifier is dropped here.
130		\begin{enumerate}
131			\item (\textbf{Consistency with points measurements}) For all $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
132			\[
133				\Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \simeq_{\delta_S} M^{(\mathrm{Point},W),u}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''}
134			\]
135			and
136			\[
137				\tilde{M}^{W,\mathrm{ind}_m(u)}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \simeq_{\delta_S} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot M^{(\mathrm{Point},W),u}_a\;,
138			\]
139			with the answer summation over $a \in \F_q$.
140			\item (\textbf{Self-consistency}) For all $W \in \{X,Z\}$ and $j \in \{1,\ldots,t\}$, on average over uniformly random $\tilde{u} \in \F_q^{M}$,
141			\[
142				\tilde{W}^j(\tilde{u}) \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \approx_{\delta_S} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{W}^j(\tilde{u})\;.
143			\]
144		\end{enumerate}
145	\end{lemma}
146	\begin{proof}
147		\uses{lem:qld-4-7, lem:qld-constructing-the-paulis-helper, def:expanded-point-measurement, def:tilde-m-measurement, def:tau-dot-product-projector, def:decoding-map, def:indicator-vector, lem:qld-win-implications, lem:qld-comm-cons, fact:add-a-proj, fact:agreement, fact:triangle, fact:data-processing, def:bracket, lem:povm-to-obs, lem:schwartz-zippel-total-degree}
148		% Support restriction added: the source (line 1492 of
149		% 14_analysis_of_the_pauli_basis_test.tex) rewrites Dec(g).ind_m(u) as
150		% g(u) for every outcome g; see Remark rem:qld-decoding-identity.
151		We first bound the mass that the marginal measurements $\{\hat{S}^W_g\}$ place on polynomials that are not encodings. On average over uniformly random $u \in \F_q^m$, the point-consistency relation \eqref{eq:qld-s-point-con-bob} of Lemma~\ref{lem:qld-4-7} gives $(\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \approx_{\delta_S} (\hat{M}^{(\mathrm{Point},W),u}_a)_{\mathrm{A}\mathrm{B}''}$ (Lemma~\ref{fact:agreement}); the consistency and Pauli-basis-consistency checks of Lemma~\ref{lem:qld-win-implications} give, again on average over uniform $u$ and combining through Lemma~\ref{fact:data-processing}, Lemma~\ref{fact:agreement}, and Lemma~\ref{fact:triangle}, that $(M^{(\mathrm{Point},W),u}_{a'})_{\mathrm{A}} \approx_{O(\eps)} (M^{(\mathrm{Pauli},W)}_{[g_h(u)=a']})_{\mathrm{A}}$; and replacing the point factor of the convolution form of $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) accordingly costs the same error, because the projectors $\tau^W_{a''}(\mathrm{ind}_m(u))$ of \eqref{eq:def-tauwu} are mutually orthogonal (Lemma~\ref{fact:add-a-proj}). Writing
152		\[
153			K^u_a = \sum_{a' + a'' = a} \bigl(M^{(\mathrm{Pauli},W)}_{[g_h(u)=a']}\bigr)_{\mathrm{A}} \ot \bigl(\tau^W_{a''}(\mathrm{ind}_m(u))\bigr)_{\mathrm{B}''}\;,
154		\]
155		a projective measurement, Lemma~\ref{fact:triangle} and Lemma~\ref{fact:agreement} therefore give, using $\delta_S \geq \eps$,
156		\[
157			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} (\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \ot (K^u_a)_{\mathrm{A}\mathrm{B}''} \ket{\hat\psi} \geq 1 - O(\delta_S)\;.
158		\]
159		Expanding $K^u_a$ over pairs $(h, h'')$ of Pauli outcomes, a term of the left-hand side with outcomes $(g, h, h'')$ is constrained by $g(u) = g_h(u) + g_{h''}(u) = g_{h + h''}(u)$, by the linearity of the encoding \eqref{eq:low-degree-encoding-definition}. If $g$ is not an encoding then $g \neq g_{h+h''}$, and both are polynomials of total degree at most $md$, so the constraint holds for at most an $md/q$ fraction of $u$ (Lemma~\ref{lem:schwartz-zippel-total-degree}). Since all terms are nonnegative and, for each $g$, the operators of the $(h,h'')$-sum add up to the identity, it follows that
160		\begin{equation}\label{eq:qld-nonencoding-mass}
161		\lean{nonencodingMarginalMass_le}
162		\notready
163		\sum_{g \,\text{not an encoding}} \bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} \,\leq\, O(\delta_S) + \frac{md}{q} \,\leq\, O(\delta_S)\;,
164		\end{equation}
165		and symmetrically with the registers $\mathrm{A}\mathrm{A}'$ in place of $\mathrm{B}\mathrm{B}'$. (If $d = 0$, every element of $\mathrm{ideg}_{d,m}(\F_q)$ is constant, hence an encoding, and the left-hand side vanishes.)
166	
167		For the first item, in the case where $M^{(\mathrm{Point},W),u}_a$ acts on register $\mathrm{A}$ and $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ on $\mathrm{B}\mathrm{B}'\mathrm{B}''$, expanding \eqref{eq:tilde_M} and \eqref{eq:def-tauwu} and using the convolution form of the combined projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) gives the exact identity
168		\[
169			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} M^{(\mathrm{Point},W),u}_a \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \ket{\hat\psi}
170			= \E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}\;.
171		\]
172		For encodings $g$ the subscript $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ equals $g(u)$; discarding the (nonnegative) terms with $g$ not an encoding and reinstating the corresponding terms with subscript $g(u)$, each of which is at most $\bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}$, shows that the right-hand side is at least
173		\[
174			\E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} - O(\delta_S)
175			\geq 1 - O(\delta_S)
176		\]
177		by \eqref{eq:qld-nonencoding-mass} and Lemma~\ref{lem:qld-4-7}, and the register-interchanged relation follows analogously. For the second item one first shows that, on average over uniformly random $\tilde{u} \in \F_q^M$,
178		\begin{equation}\label{eq:qld-pulling-cons}
179			\bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_S} \bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}\;:
180		\end{equation}
181		right-multiplying by the resolution $\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_S} \Id$ of Lemma~\ref{lem:qld-constructing-the-paulis-helper} (with Lemma~\ref{fact:add-a-proj}) and expanding the products of $\tau^W$ projectors via \eqref{eq:def-tauwu} and $h \cdot \mathrm{ind}_m(u) = g_h(u)$ places $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{A}\mathrm{A}'\mathrm{A}''}$ within $O(\delta_S)$ of a sum over pairs $(g,h)$ with $(\mathrm{Dec}(g)-h)\cdot\tilde{u} = a$. One then applies, in turn, the self-consistency of the points measurements (Lemma~\ref{lem:qld-win-implications}) at cost $\eps$; the exact identity $\ket{\hat\psi} = \sum_{h'} (\tau^W_{h'})_{\mathrm{B}'} \ot (\tau^W_{h'})_{\mathrm{B}''} \ket{\hat\psi}$ of the EPR registers; Lemma~\ref{lem:qld-constructing-the-paulis-helper} twice more (once through a Cauchy--Schwarz detour of cost $O(\sqrt{\eps})$ using the self-consistency of the $\hat{M}^{(\mathrm{Point},W),u}_a$, Lemma~\ref{lem:qld-comm-cons}); and finally a Schwartz--Zippel step (Lemma~\ref{lem:schwartz-zippel-total-degree}, for polynomials of total degree at most $md$) which replaces the event $(g'-g_{h'})(u) = (g-g_h)(u)$ by the polynomial identity $g'-g_{h'} = g-g_h$ at cost $md/q$. The resulting expression
182		\[
183			\sum_{\substack{g,h,g',h': \\ g' - g_{h'} = g - g_h \\ (\mathrm{Dec}(g)-h)\cdot \tilde{u} = a}}
184			\Bigl((\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\tau_h^W)_{\mathrm{A}''} \Bigr) \cdot \Bigl( (\hat{S}^W_{g'})_{\mathrm{B}\mathrm{B}'} \ot (\tau_{h'}^W)_{\mathrm{B}''} \Bigr)
185		\]
