243	\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
244		\lean{MIPStarRE.QPBT.swapUnitary_mul_conjTranspose}
245		\lean{MIPStarRE.QPBT.conjTranspose_mul_swapUnitary}
