257		\begin{equation}\label{eq:qld-unitary-6}
258			V_{\mathrm{B}} \, \tilde{M}^{W,\mathrm{ind}_m(u)}_a \, V_{\mathrm{B}}^\dagger = \Id_{\mathrm{B}\mathrm{B}'} \ot (\tau^W_{[g_h(u)=a]})_{\mathrm{B}''}\;,
259			\qquad
260			\tau^W_{[g_h(u)=a]} = \sum_{h \,:\, g_h(u) = a} \tau^W_h\;,
261		\end{equation}
262		together with the analogous identity for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$.
263	\end{lemma}
264	\begin{proof}
265		\uses{lem:qld-4-7, lem:tildew-product-form, lem:twisted-commutation, def:v-swap-unitary, def:tilde-m-measurement, def:tau-dot-product-projector, def:indicator-vector, def:decoding-map, def:generalized-pauli}
266		Since the measurement $\{\hat{S}_{g_X,g_Z}\}$ is projective (Lemma~\ref{lem:qld-4-7}) and the $\tau^X, \tau^Z$ observables are self-inverse,
267		\[
268			V_{\mathrm{A}} V_{\mathrm{A}}^\dagger = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \Id_{\mathrm{A}''} = \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''}\;,
269		\]
270		and the same computation gives $V_{\mathrm{A}}^\dagger V_{\mathrm{A}} = \Id$, so $V_{\mathrm{A}}$ is unitary; likewise $V_{\mathrm{B}}$. For \eqref{eq:v-swap-obs-conjugation}, conjugate the product form \eqref{eq:tildewj-product-form} of $\tilde{W}^j(\tilde{u})$ (Lemma~\ref{lem:tildew-product-form}): by the orthogonality of the projectors $\hat{S}_{g_X,g_Z}$, only the diagonal terms survive, and the twisted commutation relation (Lemma~\ref{lem:twisted-commutation})
271		\[
272			\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X)) \, \tau^W(e_j \tilde{u}) = (-1)^{\tr( e_j(\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \tau^W(e_j \tilde{u}) \, \tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))
273		\]
274		cancels the sign $(-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))}$ term by term, leaving $\sum_{g_X,g_Z} \hat{S}_{g_X,g_Z} \ot \tau^W(e_j \tilde{u}) = \Id \ot \tau^W(e_j \tilde{u})$. For \eqref{eq:qld-unitary-6}, expand $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ by \eqref{eq:tilde_M} and \eqref{eq:def-tauwu}; by the orthogonality of the $\hat{S}_{g_X,g_Z}$, conjugation replaces, in the term of $\hat{S}^W_g$, each projector $\tau^W_h$ by $\tau^W_{h + \mathrm{Dec}(g)}$, using the identities $\tau^X(s)\, \tau^Z_h \,\tau^X(s)^\dagger = \tau^Z_{h+s}$ and $\tau^Z(s)\, \tau^X_h\, \tau^Z(s)^\dagger = \tau^X_{h+s}$. Substituting $h' = h + \mathrm{Dec}(g)$ turns the constraint $h \cdot \mathrm{ind}_m(u) = (\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)) - a$ into $h' \cdot \mathrm{ind}_m(u) = -a = a$, since $\F_q$ has characteristic $2$; the quantity $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ cancels exactly, so no relation between it and $g(u)$ is used (Remark~\ref{rem:qld-decoding-identity}). Since $h' \cdot \mathrm{ind}_m(u) = g_{h'}(u)$ \eqref{eq:low-degree-encoding-definition}, summing over $g$ gives \eqref{eq:qld-unitary-6}; the computation for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ is identical.
275	\end{proof}
